"""Render the configuration reference as JSON or as ``docs/configuration.md``. Pure functions over
``config_reference.reference()``."""

from __future__ import annotations

import json
from collections.abc import Iterable
from dataclasses import asdict
from itertools import groupby

from rastro.config_catalog import CONFIG_RULE, PYTHON_MODELS, SECTIONS
from rastro.config_reference import ConfigEntry, reference

_HEAD = """\
# Configuration reference

<!-- Generated by `rastro config --output markdown`; edit the models,
src/rastro/config_descriptions.py or src/rastro/config_catalog.py instead. -->

Every option Rastro accepts, generated from its code: job-file keys, Python keyword
arguments, operator grants, environment variables and command-line flags. Job files reject
unknown keys, and `rastro job validate` suggests the closest valid one. If what you need is
not here, check [Capabilities](capabilities.md) and write a gap report instead of inventing
an option.

- `rastro config --output json` prints this reference; MCP clients read
  `rastro://configuration`.
- `rastro job template` prints an annotated job file with every option commented;
  `rastro job template --all` adds every recipe, field, source, model and rule variant.

## Job file

A path names a key: `sources[].url` is `url` inside a `[[sources]]` entry, and
`acquisition.egress_profiles.<name>.proxy_url` is `proxy_url` under
`[acquisition.egress_profiles.NAME]`. Keys listed under a variant exist only when that
discriminator value is set. "Same keys as" means the table repeats another one.
"""


def render_json(version: str | None = None) -> str:
    """Machine-readable reference for ``rastro config`` and ``rastro://configuration``."""
    payload = {
        "schema_version": 1,
        "rastro_version": version,
        "rule": CONFIG_RULE,
        "sections": SECTIONS,
        "python_models": PYTHON_MODELS,
        "entries": [asdict(entry) for entry in reference()],
    }
    return json.dumps(payload, indent=2) + "\n"


def render_markdown() -> str:
    """The docs page ``docs/configuration.md``."""
    entries = reference()
    by_kind = {kind: [e for e in entries if e.kind == kind] for kind in ("job", "python")}
    lines = [_HEAD]
    lines += _job_sections(by_kind["job"])
    lines += _python_section(by_kind["python"])
    lines += _simple_section(
        "Operator grants",
        "Only the person running Rastro can grant these; a job file never can.",
        ("Flag", "Also", "What it allows", "Docs"),
        [
            (f"`{e.path}`", e.bounds, e.description, _link(e.docs))
            for e in entries
            if e.kind == "grant"
        ],
    )
    lines += _simple_section(
        "Environment variables",
        "Besides the grant variables above. Values are never stored in job files.",
        ("Variable", "What it does", "Docs"),
        [(f"`{e.path}`", e.description, _link(e.docs)) for e in entries if e.kind == "env"],
    )
    lines += _cli_section([e for e in entries if e.kind == "cli"])
    return "\n".join(lines).rstrip("\n") + "\n"


def _job_sections(entries: list[ConfigEntry]) -> list[str]:
    lines: list[str] = []
    top = [e for e in entries if "." not in e.path and "[" not in e.path]
    sections = {_root(e.path) for e in entries if e.path != _root(e.path)} | {
        e.path for e in top if e.same_as
    }
    scalars = [e for e in top if e.path not in sections]
    lines += ["### Top-level keys", "", *_job_table(scalars), ""]
    for name in (e.path for e in top if e.path in sections):
        head = next(e for e in top if e.path == name)
        brackets = f"[[{name}]]" if head.type.startswith("array") else f"[{name}]"
        lines += [f"### `{brackets}`", "", f"{head.description} Docs: {_link(head.docs)}.", ""]
        members = [e for e in entries if _root(e.path) == name and e.path != name]
        for variant, group in groupby(members, key=lambda e: e.variant):
            if variant:
                lines += [f"#### `{variant}`", ""]
            lines += [*_job_table(list(group)), ""]
    return lines


def _root(path: str) -> str:
    return path.split(".", 1)[0].removesuffix("[]")


def _job_table(entries: Iterable[ConfigEntry]) -> list[str]:
    rows = ["| Key | Type | Default | Bounds | Description |", "| --- | --- | --- | --- | --- |"]
    for e in entries:
        text = e.description + (f" Same keys as `{e.same_as}`." if e.same_as else "")
        rows.append(_row(f"`{e.path}`", e.type, _default(e), _code(e.bounds), text))
    return rows


def _python_section(entries: list[ConfigEntry]) -> list[str]:
    models = ", ".join(
        f"`rastro.{m}(...)` takes the `[{s}]` keys" for m, s in PYTHON_MODELS.items()
    )
    lines = ["## Python keyword arguments", "", f"{models}.", ""]
    for function, group in groupby(entries, key=lambda e: e.path.split("(", 1)[0]):
        items = list(group)
        lines += [f"### `{function}`", "", f"Docs: {_link(items[0].docs)}.", ""]
        lines += ["| Argument | Type | Default | Description |", "| --- | --- | --- | --- |"]
        for e in items:
            argument = e.path.split("(", 1)[1].rstrip(")")
            lines.append(_row(f"`{argument}`", f"`{e.type}`", _default(e), e.description))
        lines.append("")
    return lines


def _simple_section(
    title: str, intro: str, header: tuple[str, ...], rows: list[tuple[str, ...]]
) -> list[str]:
    table = ["| " + " | ".join(header) + " |", "|" + " --- |" * len(header)]
    return [f"## {title}", "", intro, "", *table, *(_row(*row) for row in rows), ""]


def _cli_section(entries: list[ConfigEntry]) -> list[str]:
    lines = ["## Command line", "", "Output is JSON unless a flag says otherwise.", ""]
    commands = [e for e in entries if e.type == "command"]
    for command in [ConfigEntry("rastro", "cli", "command", None, False, "", "", ""), *commands]:
        flags = [e for e in entries if e.type != "command" and _owner(e.path) == command.path]
        title = "Global flags" if command.path == "rastro" else f"`{command.path}`"
        lines += [f"### {title}", ""]
        if command.description:
            lines += [f"{command.description}. Docs: {_link(command.docs)}.", ""]
        if flags:
            lines += ["| Flag | Value | Default | Choices | Description |"]
            lines += ["| --- | --- | --- | --- | --- |"]
            for e in flags:
                name = e.path.removeprefix(command.path + " ")
                lines.append(_row(f"`{name}`", e.type, _default(e), e.bounds, e.description))
            lines.append("")
    return lines


def _owner(path: str) -> str:
    return path.rsplit(" ", 1)[0]


def _default(entry: ConfigEntry) -> str:
    if entry.required:
        return "required"
    return "-" if entry.default in (None, "null") else _code(entry.default or "")


def _code(text: str) -> str:
    if not text:
        return ""
    fence = "``" if "`" in text else "`"
    pad = " " if fence == "``" else ""
    return f"{fence}{pad}{text}{pad}{fence}"


def _link(docs: str) -> str:
    target = docs.removeprefix("docs/")
    return f"[{target}]({target})"


def _row(*cells: str) -> str:
    return "| " + " | ".join(cell.replace("|", "\\|").replace("\n", " ") for cell in cells) + " |"
